	isVipEvent: function() {
    var eventId = this.getParameter('sysparm_event_id');
    var gr = new GlideRecord('x_1790116_event_ma_event');

    if (gr.get(eventId)) {
        // Assuming u_vip is a boolean or string field storing '1' or 'true'
        var vip = gr.getValue('u_vip');
        if (vip === '1' || vip === 'true' || vip === true) {
            return 'true';
        } else {
            return 'false';
        }
    }
    return 'false';
},







    type: 'EventUtilsClient'
